def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    my_d = me.count('D')
    opp_d = opp.count('D')
    last_me = me[-1]
    last_opp = opp[-1]

    if my_d > 0:
        ret = 0
        for i in range(n):
            if me[i] == 'D' and i + 1 < n and opp[i+1] == 'D':
                ret += 1
        ret_rate = ret / my_d
    else:
        ret_rate = 1.0

    if n < 5:
        return 'C'

    if opp_d * 5 > n * 4:
        if n % 10 == 0:
            return 'C'
        return 'D'

    if my_d == 0:
        if opp_d == 0 and n >= 10:
            return 'D'
        if last_opp == 'D':
            return 'D'
        return 'C'

    if ret_rate < 0.3:
        if last_opp == 'D':
            return 'D'
        if my_d >= 5 and ret_rate < 0.1:
            if n % 2 == 0:
                return 'D'
            return 'C'
        if my_d >= 3 and ret_rate < 0.2:
            if n % 3 == 0:
                return 'D'
            return 'C'
        if n % 4 == 0:
            return 'D'
        return 'C'
    else:
        if last_opp == 'D':
            if last_me == 'D':
                streak = 0
                for a in reversed(opp):
                    if a == 'D':
                        streak += 1
                    else:
                        break
                if streak >= 2:
                    return 'C'
                return 'D'
            else:
                if n >= 2 and opp[-2] == 'C':
                    return 'C'
                return 'D'
        else:
            if last_me == 'D':
                return 'C'
            if n >= 95 and ret_rate < 0.5:
                if n % 2 == 0:
                    return 'D'
            return 'C'
